const item = $input.first() ?? { json: {}, binary: {} };
const incoming = item.json ?? {};
let payload = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;

// Some clients/proxies may send the JSON document as a binary upload.
// If the parsed body is empty, safely try known raw-body/binary representations.
if ((!payload || Object.keys(payload).length === 0) && typeof incoming.rawBody === 'string') {
  try { payload = JSON.parse(incoming.rawBody); } catch {}
}
if ((!payload || Object.keys(payload).length === 0) && item.binary && Object.keys(item.binary).length) {
  const binaryProperty = Object.keys(item.binary)[0];
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryProperty);
  const raw = buffer.toString('utf8').replace(/^\uFEFF/, '').trim();
  try { payload = JSON.parse(raw); } catch {
    payload = {};
  }
}

if (!payload || typeof payload !== 'object' || Array.isArray(payload)) payload = {};
const brief = typeof payload.brief === 'string' ? payload.brief.trim() : '';
const allowed = new Set(['instagram', 'facebook', 'tiktok', 'youtube', 'x', 'linkedin']);
const requestedPlatforms = Array.isArray(payload.platforms)
  ? payload.platforms
  : (typeof payload.platforms === 'string' ? [payload.platforms] : []);
const platforms = requestedPlatforms
  .filter((p) => typeof p === 'string')
  .map((p) => p.trim().toLowerCase())
  .filter((p) => allowed.has(p));
const errors = [];
if (!brief) errors.push('Missing required field: brief');
if (requestedPlatforms.length === 0) errors.push('Missing required field: platforms');
if (brief.length < 10) errors.push('brief must contain at least 10 characters');
if (brief.length > 5000) errors.push('brief must be 5000 characters or fewer');
if (platforms.length !== requestedPlatforms.length) errors.push('Unsupported or invalid platforms detected');
const requestId = typeof payload.request_id === 'string' && payload.request_id.trim()
  ? payload.request_id.trim()
  : `apex_${Date.now()}`;
const valid = errors.length === 0;
return [{
  json: {
    httpStatus: valid ? 200 : 400,
    response: valid
      ? {
          ok: true,
          request_id: requestId,
          stage: 'intake_validated',
          mode: 'foundation_only',
          approval_required: true,
          message: 'Request format validated. AI generation and Supabase persistence are not connected in this starter workflow.',
          received: { platforms, brief_length: brief.length }
        }
      : { ok: false, request_id: requestId, error: 'INVALID_CONTENT_REQUEST', details: errors }
  }
}];
